//! USB HID usage <-> platform key code tables.
//!
//! The wire carries USB HID usages (`(page << 16) | usage`), so the protocol is
//! platform-neutral. The viewer maps `KeyboardEvent.code` -> HID; the macOS agent maps
//! HID -> `kVK_*` virtual keycode; the Windows agent maps HID -> set-1 scancode
//! (`0xE0xx` = extended, i.e. `KEYEVENTF_EXTENDEDKEY`).
//!
//! `keymap_gen.rs` is GENERATED by `tools/gen-keymap` from Chromium's
//! `ui/events/keycodes/dom/dom_code_data.inc` (BSD-3-Clause, see THIRD_PARTY_NOTICES.md).
//! Do not edit it by hand.

#[path = "keymap_gen.rs"]
mod generated;

pub use generated::KEYS;

/// HID usage page for keyboard/keypad.
pub const HID_PAGE_KEYBOARD: u32 = 0x07;
/// HID usage page for consumer controls (media keys).
pub const HID_PAGE_CONSUMER: u32 = 0x0c;

/// Combine an HID page and usage id into the wire value.
pub const fn hid(page: u32, usage: u32) -> u32 {
    (page << 16) | usage
}

/// One row of the key table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct KeyEntry {
    /// `(page << 16) | usage`
    pub hid: u32,
    /// DOM `KeyboardEvent.code`, e.g. "KeyA".
    pub code: &'static str,
    /// macOS virtual keycode (`kVK_*`), if the key exists on macOS.
    pub mac: Option<u16>,
    /// Windows set-1 scancode; `0xE0xx` means extended. `None` if no scancode.
    pub win: Option<u16>,
}

/// Look up the table row for an HID usage.
pub fn by_hid(hid: u32) -> Option<&'static KeyEntry> {
    KEYS.iter().find(|k| k.hid == hid)
}

/// Look up the HID usage for a DOM `KeyboardEvent.code`.
pub fn hid_for_code(code: &str) -> Option<u32> {
    KEYS.iter().find(|k| k.code == code).map(|k| k.hid)
}

/// macOS virtual keycode for an HID usage.
pub fn mac_keycode(hid: u32) -> Option<u16> {
    by_hid(hid).and_then(|k| k.mac)
}

/// Windows scancode for an HID usage (`0xE0xx` = extended).
pub fn win_scancode(hid: u32) -> Option<u16> {
    by_hid(hid).and_then(|k| k.win)
}

/// The table row for a Windows set-1 scancode (`0xE0xx` = extended, i.e. the low-level
/// keyboard hook's `scanCode | 0xE000` when `LLKHF_EXTENDED` is set).
pub fn by_win_scancode(scancode: u16) -> Option<&'static KeyEntry> {
    KEYS.iter().find(|k| k.win == Some(scancode))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn windows_scancodes_map_back_to_codes() {
        let code = |sc| by_win_scancode(sc).map(|k| k.code);
        assert_eq!(code(0x000f), Some("Tab"));
        assert_eq!(code(0x0038), Some("AltLeft"));
        assert_eq!(code(0xe038), Some("AltRight"));
        assert_eq!(code(0xe05b), Some("MetaLeft"));
        assert_eq!(code(0xe048), Some("ArrowUp"));
        assert_eq!(code(0x0048), Some("Numpad8"));
        // Every scancode in the table is unique.
        for k in KEYS.iter().filter(|k| k.win.is_some()) {
            assert_eq!(
                by_win_scancode(k.win.unwrap()).unwrap().hid,
                k.hid,
                "{}",
                k.code
            );
        }
    }

    #[test]
    fn basic_keys() {
        assert_eq!(hid_for_code("KeyA"), Some(0x0007_0004));
        assert_eq!(mac_keycode(0x0007_0004), Some(0x00)); // kVK_ANSI_A
        assert_eq!(mac_keycode(hid_for_code("Enter").unwrap()), Some(0x24)); // kVK_Return
        assert_eq!(mac_keycode(hid_for_code("MetaLeft").unwrap()), Some(0x37)); // kVK_Command
        assert_eq!(win_scancode(hid_for_code("KeyA").unwrap()), Some(0x001e));
        assert_eq!(win_scancode(hid_for_code("ArrowUp").unwrap()), Some(0xe048));
        // table must not contain duplicate HID usages or codes
        for (i, a) in KEYS.iter().enumerate() {
            for b in &KEYS[i + 1..] {
                assert_ne!(a.hid, b.hid, "duplicate hid {:#x}", a.hid);
                assert_ne!(a.code, b.code, "duplicate code {}", a.code);
            }
        }
    }
}
